import{_ as t,l as r,o as i,c as n,v as e,p as s,x as o,d as p,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Phi-3 技术报告","description":"","frontmatter":{"title":"Phi-3 技术报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/phi3-report.md","filePath":"llm/phi3-report.md","lastUpdated":1789023840000}'),d={name:"llm/phi3-report.md"};function B(P,a,E,c,T,g){const l=r("Mermaid");return i(),n("div",null,[a[1]||(a[1]=e('<h1 id="phi-3-技术报告" tabindex="-1">Phi-3 技术报告 <a class="header-anchor" href="#phi-3-技术报告" aria-label="Permalink to &quot;Phi-3 技术报告&quot;">​</a></h1><div class="epigraph"><p>创新完全在训练数据上：把 phi-2 用过的那套「过滤网页 + 合成数据」放大，得到一个小到能在手机上跑、质量却接近 Mixtral 8x7B 与 GPT-3.5 的模型。</p><footer>—— Abdin 等，Phi-3 Technical Report，arXiv:2404.14219</footer></div><p>Microsoft 的 Phi 线从教材式代码小模型走到能进手机的通用档。2024 年 4 月的技术报告主推 <strong>phi-3-mini：3.8B，训 3.3T token</strong>，默认 4K 上下文，并给出 7B（small）与 14B（medium）的参数缩放。路线主张见 <a href="/llm/phi">Phi 小模型</a>；本篇按报告写三档规格、两阶段预训练、LongRoPE 128K，以及后来补进同一份 PDF 的 phi-3.5 变体——不把 <a href="/llm/phi-4">phi-4</a> 的 14B 合成主体写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kaplan / Chinchilla 默认数据是固定质量的互联网切片。Phi 要问的是：在 <strong>数 B 参数、数 T token</strong> 上，若把网页按教育价值滤到接近教材、再用 LLM 合成推理轨迹，小模型能否达到通常认为只有 7B×8 专家或 GPT-3.5 才有的综合分。报告把这称作靠近「data optimal」：不是算力最优，也不是无限过训练，而是给定尺度下把不该占容量的事实（某日球赛比分）剔掉，把推理结构留下来。</p><p>部署约束同样硬。3.8B 4-bit 约 <strong>1.8GB</strong>，报告在 iPhone 14 A16 上离线测到超过 12 tok/s。架构若标新立异，开源推理栈接不上；因此 mini 刻意对齐 Llama-2 块结构与词表。</p><h3 id="mini-对齐-llama-2-small-才换词表与稀疏注意力" tabindex="-1">mini 对齐 Llama-2，small 才换词表与稀疏注意力 <a class="header-anchor" href="#mini-对齐-llama-2-small-才换词表与稀疏注意力" aria-label="Permalink to &quot;mini 对齐 Llama-2，small 才换词表与稀疏注意力&quot;">​</a></h3><p><strong>phi-3-mini</strong>：解码器，隐宽 3072，32 头 32 层，词表 <strong>32064</strong>（Llama-2 词表去掉 BoS、加聊天符），bfloat16，3.3T token，默认 4K。聊天模板为 <code>&lt;|user|&gt;</code> / <code>&lt;|assistant|&gt;</code>。LongRoPE 把窗口扩到 128K，称 phi-3-mini-128K。</p><p><strong>phi-3-small（7B）</strong>：tiktoken 词表 <strong>100352</strong>，默认 8K；32 头 32 层，隐宽 4096；<a href="/llm/swiglu">GEGLU</a>；用 μP 在小代理模型上调超参再迁移；<a href="/llm/gqa">GQA</a> 为 4 个查询共享 1 个键；<strong>blocksparse 注意力</strong>与稠密层交替，头之间用不同稀疏图案覆盖上下文，以减 KV。训练与推理各有 Triton / paged 核。约 10% 多语数据。</p><p><strong>phi-3-medium（14B）</strong>：与 mini 同词表同块结构，40 头 40 层，隐宽 5120，训 <strong>4.8T</strong>（与 small 相同总量、略多 epoch）。报告观察到部分基准从 7B 到 14B 的涨幅小于从 3.8B 到 7B，怀疑 14B 上数据混合还没处在「data optimal」。</p><p><span class="marginnote">MMLU 5-shot：mini 68.8，small 75.7，medium 78.0；MT-bench 8.38 / 8.70 / 8.91（报告表，同一内部管线）。这些是他们的评测口径，和 Open LLM Leaderboard 的 shot 设定不必相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练两段、互不相交。Phase-1 以网页为主，教通用语言与知识。Phase-2 把 Phase-1 里滤得更狠的子集，与教逻辑推理和专项技能的合成数据合并。过滤轴是教育价值：同一条网页，对前沿大模型可能是好知识，对 mini 可能是占容量的噪声。合成数据延续 <em>Textbooks Are All You Need</em> 的教师生成教材/习题，不是无约束刷竞赛题。</p><p>后训练两段：SFT 覆盖数学、代码、推理、对话、身份与安全；DPO 把不想要的行为当 rejected，并含负责任 AI 数据。SFT 先走英语。长上下文版本另做中训，再在长短混合上做 SFT 与 DPO，使 128K 档在短任务上不掉点。</p><h3 id="phi-3-5-多语、moe-与视觉" tabindex="-1">phi-3.5：多语、MoE 与视觉 <a class="header-anchor" href="#phi-3-5-多语、moe-与视觉" aria-label="Permalink to &quot;phi-3.5：多语、MoE 与视觉&quot;">​</a></h3><p>同一份后续修订引入 phi-3.5-mini、phi-3.5-MoE、phi-3.5-Vision。中训加多语与长文本，仍用 LongRoPE，混合窗口把 4K 任务与 128K 一起保住。MoE 为 16 个专家、top-2，每个专家是独立 GLU；16×3.8B 总量约 42B、激活约 <strong>6.6B</strong>，路由用 SparseMixer。Vision 约 4.2B，从 mini 扩，支持单图与多图。RULER 上 128K 仍有明显掉点，报告归因为中训长数据不够，而不是 LongRoPE 公式本身。</p>',16)),(i(),s(m,null,{default:o(()=>[h(l,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20WEB%5B%22%E6%8C%89%E6%95%99%E8%82%B2%E4%BB%B7%E5%80%BC%E8%BF%87%E6%BB%A4%E7%9A%84%E7%BD%91%E9%A1%B5%22%5D%20--%3E%20P1%5B%22Phase-1%20%E9%80%9A%E7%94%A8%E7%9F%A5%E8%AF%86%22%5D%0A%20%20WEB%20--%3E%20P2%5B%22Phase-2%20%E6%9B%B4%E7%8B%A0%E8%BF%87%E6%BB%A4%22%5D%0A%20%20SYN%5B%22%E5%90%88%E6%88%90%E6%8E%A8%E7%90%86%E4%B8%8E%E4%B8%93%E9%A1%B9%22%5D%20--%3E%20P2%0A%20%20P1%20--%3E%20P2%0A%20%20P2%20--%3E%20MINI%5B%22phi-3-mini%203.8B%20%40%203.3T%22%5D%0A%20%20P2%20--%3E%20SM%5B%22phi-3-small%207B%20%40%204.8T%22%5D%0A%20%20P2%20--%3E%20MD%5B%22phi-3-medium%2014B%20%40%204.8T%22%5D%0A%20%20MINI%20--%3E%20SFT%5B%22SFT%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22DPO%22%5D%0A%20%20DPO%20--%3E%20LR%5B%22LongRoPE%20%E4%B8%AD%E8%AE%AD%20%E2%86%92%20128K%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>小模型的参数装不下长尾百科。教材式过滤把梯度用在可迁移的解题步骤上；合成轨迹提供左到右可预测的「喂勺」过程，与人类网页里答案前置、编辑非线性相反。结果是 GSM8K / HumanEval 一类与教材同分布的任务可以打过更大的脏数据模型；TriviaQA 这类事实检索上，Mixtral / GPT-3.5 仍然可以明显领先——报告表里这不是隐藏项。</p><p>mini 对齐 Llama-2，是为了让 vLLM、llama.cpp 一类栈几乎零改动。small 换 tiktoken 与 blocksparse，是 7B 上多语压缩和 KV 开始成为瓶颈：词表负责切得动非英语，稀疏头负责 8K+ 的缓存。μP 则把 7B 的学习率从代理模型迁过来，减少再扫一遍的成本。</p><p><span class="marginnote">「创新完全在数据」是报告原句，指向相对架构论文而言。small 的 blocksparse、GQA、GEGLU、μP 仍是架构选择。读 mini 时这句话成立；读 small 时不要删掉稀疏注意力。</span></p><h3 id="和「手机-3-8b-gpt-3-5」话术" tabindex="-1">和「手机 3.8B = GPT-3.5」话术 <a class="header-anchor" href="#和「手机-3-8b-gpt-3-5」话术" aria-label="Permalink to &quot;和「手机 3.8B = GPT-3.5」话术&quot;">​</a></h3><p>对标的是报告自己的学术表与内部测试，不是 ChatGPT 产品。4-bit 手机速度证明的是可部署，不证明长尾知识、工具使用或多语聊天全面达到 GPT-3.5。128K 档在 RULER 长档掉点，说明 LongRoPE 给的是长度许可，不是免费的针检索 SOTA。14B 涨幅变缓，说明「同一锅数据放大参数」会先碰到数据最优而不是算力最优。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>数据管线与污染审计不随权重开源。复现「教科书」若只剩「让 GPT 写伪教材」，会得到风格华丽、评测虚高的模型。mini 的 32k 词表对非拉丁脚本碎；要多语应看 small / 3.5，而不是假设 3.8B 聊天模型自动会中文。blocksparse 需要他们描述过的核，朴素 SDPA 实现会又慢又对不齐数值。</p><p>安全与幻觉：小模型更会「教材腔地错」。SFT/DPO 把模型变成助手，不自动变成可引用的知识库。phi-3.5-MoE 的 42B 总量决定装载，6.6B 激活决定算力，两者不要混着写 SLA。手机叙事只绑在量化后的 mini：small 的 blocksparse 核与 medium 的 14B 宽度都不在 A16 的 1.8GB 故事里。把三档都写成「能进手机」是把部署口号从 3.8B 误扩到全家。内部评测管线对所有对照模型共用同一套 few-shot，报告强调他们没有为 phi-3 单独改提示——这降低了「自家模型调 prompt」的口实，也意味着与公开 leaderboard 数字不必逐格相等。</p><p><span class="marginnote">引用 arXiv:2404.14219。phi-3.5 写在同一报告后续版本里，不要另编一篇不存在的「Phi-3.5 会议论文」。Phi-2 仍以微软博客为出处。不要把 phi-4 的 tiktoken 100352 与 16K 中训安到 phi-3-mini 上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>phi-3-mini 为 3.8B / 3.3T / 4K，Llama-2 式块与 32064 词表，4-bit 可在手机离线跑。</li><li>small 7B 与 medium 14B 训 4.8T；small 换 tiktoken、GQA 与 blocksparse；medium 扩深宽但部分榜涨幅变缓。</li><li>预训练两阶段（通用网页 → 更狠过滤 + 合成推理）；后训练 SFT + DPO；128K 走 LongRoPE。</li><li>质量主张是数据最优而不是新注意力核；事实类基准仍可能落后更大模型。</li><li>出处：Abdin 等，<em>Phi-3 Technical Report: A Highly Capable Language Model Locally on Your Phone</em>，arXiv:2404.14219，2024。</li></ul>',12))])}const b=t(d,[["render",B]]);export{u as __pageData,b as default};
